declare(strict_types=1);require_once dirname(__DIR__,2).'/config.php';require_once BASE_PATH.'/shared/accounts-sage.php';sage_require_owner();sage_schema_ready();header('Cache-Control:no-store');function sage_reply(array$d,int$s=200):void{http_response_code($s);header('Content-Type:application/json; charset=utf-8');echo json_encode($d,JSON_UNESCAPED_SLASHES);exit;}try{$action=(string)($_REQUEST['action']??'list');$month=sage_month((string)($_REQUEST['month']??date('Y-m')));if($action==='export'){$d=sage_payload($month);header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename="sage-posting-pack-'.$month.'.csv"');$o=fopen('php://output','w');fputcsv($o,['Sage Posting & Reconciliation',$month]);fputcsv($o,['Customer',$d['posting_pack']['customer']]);fputcsv($o,[]);fputcsv($o,['Sales Posting']);foreach($d['posting_pack'] as$k=>$v)fputcsv($o,[str_replace('_',' ',ucwords($k,'_')),$v]);fputcsv($o,[]);fputcsv($o,['Portal sales',$d['portal_sales']]);fputcsv($o,['Sage posted',$d['sage_posted']]);fputcsv($o,['Sales difference',$d['sales_difference']]);fputcsv($o,['VAT difference',$d['vat_difference']]);fputcsv($o,[]);fputcsv($o,['Bank Receipt Reconciliation']);fputcsv($o,['Portal expected',$d['expected_receipts_total']]);fputcsv($o,['Bank/Sage receipts',$d['bank_receipts_total']]);fputcsv($o,['Explained difference',$d['explained_difference']]);fputcsv($o,['Unexplained difference',$d['bank_difference']]);fputcsv($o,[]);fputcsv($o,['Purchase date','Supplier','Description','Invoice','Incl VAT','Input VAT','Excl VAT','Sage account','VAT code','Status']);foreach($d['purchases']as$p)fputcsv($o,[$p['purchase_date'],$p['supplier'],$p['description'],$p['invoice_reference'],$p['amount_incl_vat'],$p['vat_amount'],$p['amount_excl_vat'],$p['sage_account'],$p['vat_code'],$p['sage_status']]);fclose($o);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){sage_verify((string)($_POST['csrf']??''));$u=current_user();$before=sage_period($month);if($action==='settings'){$maps=[];foreach(['standard_account','standard_vat_code','zero_account','shipping_account','discount_account','refund_account']as$k)$maps[$k]=trim((string)($_POST[$k]??''));$customer=trim((string)($_POST['customer_name']??''));if($customer==='')throw new RuntimeException('Enter the Sage customer name.');db()->prepare('UPDATE accounts_sage_settings SET customer_name=?,posting_mode=?,bank_statement_method=?,account_mapping_json=?,updated_by=?,updated_by_name=? WHERE id=1')->execute([$customer,'summary_monthly',(string)($_POST['bank_statement_method']??'manual_sage_upload'),json_encode($maps,JSON_UNESCAPED_SLASHES),(int)$u['id'],(string)$u['name']]);sage_audit($month,'settings_updated',null,['customer'=>$customer,'mapping'=>$maps]);}
elseif($action==='ready'){$d=sage_payload($month);if(!$d['mapping_ready'])throw new RuntimeException('Confirm the standard-rated Sage account and VAT code before marking this posting ready.');db()->prepare("INSERT INTO accounts_sage_periods(month_key,status,prepared_at,prepared_by,prepared_by_name)VALUES(?,'posting_ready',NOW(),?,?) ON DUPLICATE KEY UPDATE status='posting_ready',prepared_at=NOW(),prepared_by=VALUES(prepared_by),prepared_by_name=VALUES(prepared_by_name)")->execute([$month,(int)$u['id'],(string)$u['name']]);sage_audit($month,'posting_ready',$before,['status'=>'posting_ready']);}
elseif($action==='posted'){$customer=trim((string)($_POST['sage_customer']??''));$ref=trim((string)($_POST['sage_document_number']??''));$date=(string)($_POST['sage_posting_date']??'');$total=sage_money($_POST['sage_total']??0);$vat=sage_money($_POST['sage_vat']??0);if($customer===''||$ref===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Complete the Sage customer, document number and posting date.');db()->prepare("INSERT INTO accounts_sage_periods(month_key,status,sage_customer,sage_document_number,sage_posting_date,sage_total,sage_vat,sage_note,posted_at)VALUES(?,'posted',?,?,?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE status='posted',sage_customer=VALUES(sage_customer),sage_document_number=VALUES(sage_document_number),sage_posting_date=VALUES(sage_posting_date),sage_total=VALUES(sage_total),sage_vat=VALUES(sage_vat),sage_note=VALUES(sage_note),posted_at=NOW()")->execute([$month,$customer,$ref,$date,$total,$vat,trim((string)($_POST['sage_note']??''))]);$after=sage_payload($month);if(!$after['sales_match'])db()->prepare("UPDATE accounts_sage_periods SET status='needs_review' WHERE month_key=?")->execute([$month]);sage_audit($month,'sage_posting_recorded',$before,['reference'=>$ref,'total'=>$total,'vat'=>$vat]);}
elseif($action==='receipt'){$date=(string)($_POST['receipt_date']??'');$amount=sage_money($_POST['amount']??0);$method=trim((string)($_POST['payment_method']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$amount<=0||$method==='')throw new RuntimeException('Enter a valid receipt date, amount and payment method.');db()->prepare('INSERT INTO accounts_sage_receipts(month_key,receipt_date,amount,payment_method,bank_account,sage_reference,allocated_to_sales,timing_difference,notes,created_by,created_by_name)VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute([$month,$date,$amount,$method,trim((string)($_POST['bank_account']??'')),trim((string)($_POST['sage_reference']??'')),(int)($_POST['allocated_to_sales']??1),isset($_POST['timing_difference'])?1:0,trim((string)($_POST['notes']??'')),(int)$u['id'],(string)$u['name']]);sage_audit($month,'receipt_recorded',null,['date'=>$date,'amount'=>$amount,'method'=>$method,'revenue_control'=>'settlement_not_sales']);}
elseif($action==='review'){$explained=sage_money($_POST['explained_bank_difference']??0);$note=trim((string)($_POST['bank_difference_note']??''));$input=isset($_POST['input_vat_checked'])?1:0;$bank=isset($_POST['bank_reviewed'])?1:0;$control=trim((string)($_POST['sage_vat_control']??''));db()->prepare("INSERT INTO accounts_sage_periods(month_key,status,explained_bank_difference,bank_difference_note,input_vat_checked,bank_reviewed,sage_vat_control)VALUES(?,'reconciling',?,?,?,?,?) ON DUPLICATE KEY UPDATE status='reconciling',explained_bank_difference=VALUES(explained_bank_difference),bank_difference_note=VALUES(bank_difference_note),input_vat_checked=VALUES(input_vat_checked),bank_reviewed=VALUES(bank_reviewed),sage_vat_control=VALUES(sage_vat_control)")->execute([$month,$explained,$note,$input,$bank,$control===''?null:sage_money($control)]);sage_audit($month,'reconciliation_reviewed',$before,['explained'=>$explained,'input_checked'=>$input,'bank_reviewed'=>$bank]);}
elseif($action==='purchase'){$id=(int)($_POST['purchase_id']??0);if($id<=0)throw new RuntimeException('Purchase not found.');$possible=isset($_POST['possible_asset'])?1:0;db()->prepare('INSERT INTO accounts_sage_purchase_status(purchase_id,sage_account,vat_code,sage_status,sage_reference,possible_asset,note,updated_by,updated_by_name)VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE sage_account=VALUES(sage_account),vat_code=VALUES(vat_code),sage_status=VALUES(sage_status),sage_reference=VALUES(sage_reference),possible_asset=VALUES(possible_asset),note=VALUES(note),updated_by=VALUES(updated_by),updated_by_name=VALUES(updated_by_name)')->execute([$id,trim((string)($_POST['sage_account']??'')),trim((string)($_POST['vat_code']??'')),(string)($_POST['sage_status']??'not_posted'),trim((string)($_POST['sage_reference']??'')),$possible,trim((string)($_POST['note']??'')),(int)$u['id'],(string)$u['name']]);sage_audit($month,'purchase_reconciliation_updated',null,['purchase_id'=>$id]);}
elseif($action==='reconcile'){$d=sage_payload($month);if(!$d['can_reconcile'])throw new RuntimeException('Sales/VAT, bank receipts and Input VAT checks must all reconcile before completing this period.');db()->prepare("UPDATE accounts_sage_periods SET status='reconciled',reconciled_at=NOW(),reconciled_by=?,reconciled_by_name=? WHERE month_key=?")->execute([(int)$u['id'],(string)$u['name'],$month]);sage_audit($month,'period_reconciled',$before,['status'=>'reconciled']);}else throw new RuntimeException('Unknown action.');sage_reply(['ok'=>true,'message'=>'Sage reconciliation updated.','data'=>sage_payload($month)]);}sage_reply(['ok'=>true,'data'=>sage_payload($month)]);}catch(Throwable$e){sage_reply(['ok'=>false,'message'=>$e->getMessage()],422);}
